import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const Graph = () => {
    const [data, setData] = useState([]);
    const [lastPrice, setLastPrice] = useState(null); // Guardar el último precio

    // Función para obtener el precio del dólar a pesos mexicanos
    const fetchDollarToMXN = async () => {
        try {
            const response = await axios.get(`https://api.exchangerate-api.com/v4/latest/USD`);
            const price = response.data.rates.MXN;

            // Solo añadir un nuevo punto si el precio ha cambiado
            if (lastPrice !== price) {
                const newDataPoint = { name: `T-${data.length}`, price }; // Crear nuevo punto de datos
                setData((prevData) => [...prevData, newDataPoint]); // Añadir nuevo punto de datos
                setLastPrice(price); // Actualizar el último precio
            }
        } catch (error) {
            console.error('Error fetching dollar price:', error);
        }
    };

    useEffect(() => {
        fetchDollarToMXN(); // Llama la función al inicio
        const interval = setInterval(fetchDollarToMXN, 10000); // Actualiza cada 10 segundos
        return () => clearInterval(interval); // Limpia el intervalo al desmontar
    }, []);

    return (
        <ResponsiveContainer width="100%" height={200}>
            <LineChart data={data}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis tickFormatter={(value) => `$${value.toFixed(2)}`} />
                <Tooltip formatter={(value) => [`$${value.toFixed(2)}`, 'Precio del Dólar']} />
                <Legend />
                <Line type="monotone" dataKey="price" stroke="#8884d8" />
            </LineChart>
        </ResponsiveContainer>
    );
};

export default Graph;
